alter table public.locations enable trigger user;
-- RATE TYPES (seed.sql itself conflicts on `code`, referencing rate_types.id
-- elsewhere only via `select id from rate_types where code = ...` — so its
-- baseline rows may already exist locally under a different id than prod)
create temp table remap_rate_types (old_id uuid, new_id uuid) on commit drop;
insert into remap_rate_types (old_id, new_id)
select local.id, prod.new_id
from public.rate_types local
join (values
    ('02879291-1b92-4d0b-996d-613423d4c746'::uuid, 'BTLD'),
    ('193c1110-6347-41c0-b1fb-e8b2f29f86c5'::uuid, 'KSSADCSTO'),
    ('1d20eef4-9854-47d3-84ef-0c5177a95da5'::uuid, 'SASPECIAL'),
    ('224172d1-3ee4-4957-bc6a-75c1acd4f763'::uuid, 'AFRICA'),
    ('2f43e567-4b47-4593-b83b-55eefb49111d'::uuid, 'INTRATE'),
    ('60410446-b60b-45bd-ba08-8ad61a3b5250'::uuid, 'NETT'),
    ('78fc2fd2-ea30-4698-8bcd-df86c90c3f80'::uuid, 'RAC'),
    ('7de0ff86-1643-4b83-90fe-10772de89236'::uuid, 'KSSADC'),
    ('9679b75f-ef65-4ca9-becb-96dc3bd356ae'::uuid, 'HIGHERDOM'),
    ('b1944573-da85-4edd-9b16-ca52c9f4ad63'::uuid, 'SADC'),
    ('c3b0aadf-d135-4c3f-9257-d6fcef421c8e'::uuid, 'RVSADC'),
    ('d0ddb7fc-2f8a-4214-8f20-cc73ad15f4ae'::uuid, 'STO'),
    ('e5664421-30f5-4cc8-a5ad-c861078fc288'::uuid, 'REGIONALRATES'),
    ('e931dcc3-237e-4408-8465-81f2e237f7b9'::uuid, 'BTHD'),
    ('e95aee03-d7d8-4eae-bbe9-41c7a5a0426b'::uuid, 'RESIDENT')
  ) as prod(new_id, nat_key) on prod.nat_key = local.code
where local.id <> prod.new_id;

set session_replication_role = replica;

update public.suppliers r set base_rate_type_id = m.new_id
from remap_rate_types m where r.base_rate_type_id = m.old_id;

update public.suppliers r set quote_rate_type_id = m.new_id
from remap_rate_types m where r.quote_rate_type_id = m.old_id;

update public.rate_cards r set rate_type_id = m.new_id
from remap_rate_types m where r.rate_type_id = m.old_id;

update public.supplier_rate_adjustments r set rate_type_id = m.new_id
from remap_rate_types m where r.rate_type_id = m.old_id;

update public.booking_services r set rate_type_id = m.new_id
from remap_rate_types m where r.rate_type_id = m.old_id;

update public.rate_types local set id = m.new_id
from remap_rate_types m where local.id = m.old_id;

set session_replication_role = default;

alter table public.rate_types disable trigger user;
