select * from json_populate_recordset(null::public.suppliers, $seedjson$[{"id":"fa22aa9c-7e8d-4f7e-9abb-16cf8011d8c9","kind":"hotel_property","name":"The President Hotel","email":"FabianT@presidenthotel.co.za","phone":"+27 21 434 8111","website":"https://www.presidenthotel.co.za/","notes":null,"active":true,"created_at":"2026-07-01T08:49:07.125536+00:00","updated_at":"2026-08-20T10:33:28.966235+00:00","status":"active","location":null,"slug":"the-president-hotel","location_id":"00000000-0000-0000-0000-000000001002","single_supplement_pct":0,"description":"Just a minute's walk from Sea Point Promenade and the beach, this relaxed hotel is 6.7 km from the Table Mountain Aerial Cableway. The airy rooms and suites feature contemporary decor, en suite bathrooms, kitchenettes, and mountain or sea views, along with free WiFi and flat-screen TVs. Apartment suites offer 1 or 2 bedrooms and separate living areas.\n\nEnjoy a complimentary breakfast buffet in the restaurant, along with amenities like an outdoor pool, spa treatment rooms, exercise room, lounge bar, gift shop, hair salon, and secure parking.","default_time_start":"14:00:00","default_time_end":"11:00:00","location_area_id":null,"infant_max_age":null,"child_max_age":11,"inclusions":[],"exclusions":[],"pricing_mode":"rate_card","street_address":"4 Alexander Rd, Bantry Bay, Cape Town, 8001","emergency_phone":null,"default_contact_name":null,"base_rate_type_id":"d0ddb7fc-2f8a-4214-8f20-cc73ad15f4ae","quote_rate_type_id":null,"parent_supplier_id":null},{"id":"f7fd3463-888c-43c1-8227-b0f23e2b963d","kind":"airline","name":"Airlink","email":"4Zonlinerefunds@flyairlink.com","phone":"+27\t011 451 7301","website":"https://www.flyairlink.com/","notes":"If you need any help, please call the Airlink Reservations Support Desk between 05h00 & 21h00.\nMonday to Monday on 011 451 7300  //  Select option one or email E-ticketing@flyairlink.com","active":true,"created_at":"2026-08-14T10:45:24.259764+00:00","updated_at":"2026-08-17T19:49:40.412719+00:00","status":"active","location":null,"slug":"airlink","location_id":null,"single_supplement_pct":0,"description":"Airlink maintains over 70 aircraft, operating to more than 47 destinations in 15 African countries.","default_time_start":null,"default_time_end":null,"location_area_id":null,"infant_max_age":1,"child_max_age":11,"inclusions":[],"exclusions":[],"pricing_mode":"manual","street_address":"Building 3, Greenstone Hill Office Park, Emerald Boulevard, Greenstone Hill, Greenstone Ext. 22, Modderfontein","emergency_phone":null,"default_contact_name":null,"base_rate_type_id":"78fc2fd2-ea30-4698-8bcd-df86c90c3f80","quote_rate_type_id":null,"parent_supplier_id":null},{"id":"f70144ed-dde9-4340-828d-d03af6b5be52","kind":"hotel_property","name":"Victoria Falls Hotel","email":"reservationsspvr@victoriafallshotel.com","phone":"+263 8677 000376","website":"https://www.victoriafallshotel.com/","notes":null,"active":true,"created_at":"2026-08-13T07:12:32.259414+00:00","updated_at":"2026-08-17T19:49:40.412719+00:00","status":"active","location":null,"slug":"victoria-falls-hotel","location_id":"b53d5ed5-e65a-4b70-be34-cad755be7977","single_supplement_pct":0,"description":"This upscale hotel, designed in the Edwardian style, offers stunning views of Victoria Falls and is 2km from the Victoria Falls Bridge. The elegantly appointed rooms feature wireless internet, satellite TV, minibars, safes, and tea/coffee facilities. Room service is available 24/7, and breakfast is served in three dining venues. The hotel also has a bar with an old-world ambiance, an outdoor swimming pool with a poolside bar, a spa, and a fitness center.","default_time_start":"14:00:00","default_time_end":"10:00:00","location_area_id":null,"infant_max_age":2,"child_max_age":11,"inclusions":["Rates inclusive of a 2% Tourism Levy per person per night","In-Room Safe","Mini Bar","Wi-Fi","Telephone","Hairdryer","Fully Air Conditioned","IP TV","Express Valet Service, same-day laundry and dry clean