insert into public.templates
select * from json_populate_recordset(null::public.templates, $seedjson$[{"id":"1caafac1-1575-4f18-8261-9cbc88d44418","key":"thank_you","subject":"{{supplierName}} | {{customerName}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}},</p><p>We hope you had a wonderful journey on <strong>{{routeName}}</strong>. Thank you for travelling with Luxus Travel &amp; Tours — it was a privilege to arrange your trip.</p><p>We would love to welcome you aboard again.</p><p>Warm regards,<br>{{consultantName}}<br>Luxus Travel &amp; Tours</p>","version":2,"active":true,"created_at":"2026-07-13T20:23:38.992853+00:00","updated_at":"2026-08-04T08:39:18.108595+00:00","is_system":true,"name":null,"sort_order":9},{"id":"3c40f6c0-9058-4f8a-bd06-c2814dcf840c","key":"full_payment_request","subject":"{{supplierName}} | {{clientSurname}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}}</p><p>Thank you for your reservation request.</p><p><strong>GUEST DETAILS</strong></p><p>Please ensure that all details match those on your ID or passport.</p>{{guestInfo}}<p><strong>RESERVATION/ITINERARY DETAILS</strong></p><p>Provisional reservations are secured for the travel services listed on your confirmation invoice. Please ensure all details are correct, as travel arrangements will be issued accordingly and change fees may apply.</p><p><strong>PLEASE FIND ATTACHED</strong></p><p>Your confirmation invoice with bank details.</p><p><strong>PAYMENT SCHEDULE</strong></p><p>Full amount due {{dueDate}}: <strong>{{amountDue}}</strong></p><p><strong>PAYMENT TERMS</strong></p><p>As this reservation falls within 60 days of departure, full payment is required within 48 hours of receiving your confirmation invoice to secure your reservation.</p><p><em>**Kindly ensure that payment is received on the due date to avoid automatic cancellation.</em></p><p><strong>BANK DETAILS FOR ELECTRONIC PAYMENTS</strong></p>{{bankingDetails}}<p>Please note: the amount transferred should be exclusive of all bank charges.</p><p><strong>CREDIT CARD PAYMENTS</strong></p><p>We accept MasterCard and Visa payments via PayGate, a secure online platform. Please request the payment link from your reservation consultant to use this service. Note: there will be a 2.6% surcharge on Credit Card payments.</p><p><strong>BOOKING STATUS</strong></p><p>Your booking status will be confirmed only after we receive your full payment.</p><p><strong>TICKETS &amp; VOUCHERS</strong></p><p>After full payment is received, all travel documents will be issued, and vouchers will be sent to you electronically. Your train tickets will be provided during check-in.</p><p><strong>ADDITIONAL TRAVEL ARRANGEMENTS</strong></p><p>If you require assistance with any additional travel arrangements, such as flights, car rentals, accommodations, tours, or excursions, please do not hesitate to contact me.</p><p>I thank you for your most valued reservation. Please do not hesitate to contact me should you require further information.</p>","version":7,"active":true,"created_at":"2026-07-23T15:05:45.41298+00:00","updated_at":"2026-08-18T13:33:48.194287+00:00","is_system":true,"name":null,"sort_order":4},{"id":"586301f5-24d0-454a-921d-a3650c2027f1","key":"final_invoice","subject":"{{supplierName}} | {{clientSurname}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}},</p><p>Please find attached your final invoice <strong>{{invoiceNumber}}</strong> for <strong>{{amountDue}}</strong>, due by <strong>{{dueDate}}</strong>.</p>{{bankingDetails}}<p>Kind regards,<br>Luxus Travel &amp; Tours</p>","version":4,"active":true,"created_at":"2026-07-13T20:23:38.992853+00:00","updated_at":"2026-08-18T13:34:06.608149+00:00","is_system":true,"name":null,"sort_order":7},{"id":"7313cdc6-4fdc-4f0d-857a-0112917058a5","key":"reservation_received","subject":"{{supplierName}} | {{clientSurname}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}}</p><p>Thank you for your reservation form well received.</p><p>The confirmation invoice with payment instructions will follow shortly.</p><p>In the meantime, I have secured your suite for you.</p>","version":3,"active":true,"created_at":"2026-07-21T11:11:33.288351+00:00","updated_at":"2026-08-04T08:39:59.072954+00:00","is_system":true,"name":"Reservation Form Received","sort_order":1},{"id":"a41b7b8b-4118-4135-9056-a5cd2170e4fc","key":"payment_reminder","subject":"{{supplierName}} | {{customerName}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}},</p><p>This is a friendly reminder that invoice <strong>{{invoiceNumber}}</strong> for <strong>{{amountDue}}</strong> is due by <strong>{{dueDate}}</strong>. Please find the invoice attached.</p>{{bankingDetails}}<p>Kind regards,<br>Luxus Travel &amp; Tours</p>","version":2,"active":true,"created_at":"2026-07-13T20:23:38.992853+00:00","updated_at":"2026-08-04T08:40:20.457188+00:00","is_system":true,"name":null,"sort_order":6},{"id":"bb5a8210-9576-40bb-877d-e7bc5562c817","key":"payment_received","subject":"{{supplierName}} | {{clientSurname}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}}</p><p>Thank you very much for your payment well received.</p><p>Please find attached your amended confirmation invoice.</p><p><strong>PAYMENT SCHEDULE</strong><br>Amount received: <strong>{{receivedAmount}}</strong> – Received, thank you.</p><p>Final amount due {{finalDueDate}}: <strong>{{outstandingAmount}}</strong></p><p>Hope you have a wonderful day.</p><p></p>","version":10,"active":true,"created_at":"2026-07-21T11:11:33.288351+00:00","updated_at":"2026-08-18T13:33:58.503127+00:00","is_system":true,"name":null,"sort_order":3},{"id":"cfbfffc7-a193-4c0f-a9ed-a6de30804df2","key":"follow_up","subject":"{{supplierName}} | {{customerName}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}},</p><p>We are following up on the quotation sent on <strong>{{lastSentDate}}</strong>. Availability on peak dates can be limited — we would love to secure your suite.</p><p>Kind regards,<br>Luxus Travel &amp; Tours</p>","version":2,"active":true,"created_at":"2026-07-13T20:23:38.992853+00:00","updated_at":"2026-08-04T08:40:40.164581+00:00","is_system":true,"name":"Follow Up Email on Quotation","sort_order":5},{"id":"db2986d9-0698-4dc2-83dc-b16261c7cae2","key":"voucher_email","subject":"{{supplierName}} | {{customerName}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}}</p><p>Thank you for your most valued reservation.</p><p>Attached, you will find the following documents:</p><ul><li>Your confirmation invoice</li><li>Your travel vouchers with contact details - <em>South Africa is voucherless. The reference found on your itinerary is all you need to confirm payment for the services booked for you. Each relevant reference number needs to be given to each service provider when using their respective service. All passengers will be required to provide identification (ID or passport) when checking in to any accommodation establishment.</em></li><li>Train Itinerary &amp; Fact Sheet</li></ul><p>Please keep a copy of the travel vouchers with you for reference purposes together with your South African IDs or Passports.</p><p>Your train tickets will be given to you at the lounge when checking in for your departure.</p><p>Please read through all the documents to see if everything is correct and advise if any changes must be made.</p><p><strong>IMPORTANT INFORMATION BEFORE YOU TRAVEL</strong><br>We recommend that you do not make use of Uber services at either departure or arrival stations. Rather make use of a private transfer or the Gautrain.</p><p>As the train runs on a shared railway line, there may be occasions when it stops for a period of time. If there are any significant delays, your train manager will inform you and the necessary arrangements will be made. The train and Luxus Travel &amp; Tours cannot be held responsible or liable for any delays or changes in tour arrangements that may be caused by natural or other factors beyond our control. We strongly advise against same-day air travel on departure or arrival days due to possible train delays.</p><p><strong>We urge all our clients to take out adequate travel insurance.</strong></p><p>I wish you a safe and pleasant journey on the *** and please do not hesitate to contact me if you require any further assistance.</p>","version":4,"active":true,"created_at":"2026-07-13T20:23:38.992853+00:00","updated_at":"2026-08-04T08:40:23.306382+00:00","is_system":true,"name":null,"sort_order":8},{"id":"e02e15cd-57c1-4f51-950c-4158e6bcb0ca","key":"deposit_request","subject":"{{supplierName}} | {{clientSurname}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}}</p><p>Thank you for your {{supplierName}} reservation request.</p><p><strong>GUEST DETAILS</strong></p><p>Please ensure that all details match those on the ID or passport.</p>{{guestInfo}}<p><strong>RESERVATION/ITINERARY DETAILS</strong></p><p>Provisional reservations are secured for the travel services listed on your confirmation invoice. Please ensure all details are correct, as travel arrangements will be issued accordingly and change fees may apply.</p><p><strong>PLEASE FIND ATTACHED</strong></p><p>Your confirmation invoice with bank details.</p><p><strong>PAYMENT SCHEDULE</strong></p><p>Deposit due Now: <strong>{{depositAmount}}</strong></p><p>Final amount due {{finalDueDate}}: <strong>{{finalAmount}}</strong></p><p><strong>PAYMENT TERMS</strong></p><p>A non-refundable deposit of {{depositPercentage}}% is required within 72 hours of receiving your confirmation invoice to secure your reservation. The final payment must be made 60 days prior to departure. If the reservation is made within 60 days of the departure date, the full amount will be due 48 hours after invoicing.</p><p>**Kindly ensure that payments are received on due dates to avoid automatic cancellation.</p><p><strong>BANK DETAILS FOR ELECTRONIC PAYMENTS</strong></p>{{bankingDetails}}<p>Please note: the amounts transferred should be exclusive of all bank charges.</p><p><strong>CREDIT CARD PAYMENTS</strong></p><p>We accept MasterCard and Visa payments via PayGate, a secure online platform. Please request the payment link from your reservation consultant to use this service. Note: there will be a 2.6% surcharge on Credit Card payments.</p><p><strong>BOOKING STATUS</strong></p><p>Your booking status will be confirmed only after we receive your deposit. The reservation will be secured once full payment is made.</p><p><strong>TICKETS &amp; VOUCHERS</strong></p><p>After full payment is received, all travel documents will be issued, and vouchers will be sent to you electronically. Your train tickets will be provided during check-in.</p><p><strong>ADDITIONAL TRAVEL ARRANGEMENTS</strong></p><p>If you require assistance with any additional travel arrangements, such as flights, car rentals, accommodations, tours, or excursions, please do not hesitate to contact me.</p><p>I thank you for your most valued reservation. Please do not hesitate to contact me should you require further information.</p>","version":7,"active":true,"created_at":"2026-07-13T20:23:38.992853+00:00","updated_at":"2026-08-10T10:56:20.167797+00:00","is_system":true,"name":"Invoice Email - Deposit Request","sort_order":2},{"id":"e04e760b-f760-4f2e-9e1a-3764f3dcdc64","key":"quote_email","subject":"{{supplierName}} | {{customerName}} - {{direction}} - {{departureDateShort}}","body_html":"<p>Dear {{customerName}}</p><p>Thank you for your valued {{supplierName}} enquiry.</p><p><strong>AVAILABILITY</strong><br>On the <strong>{{direction}}</strong> departure, <strong>{{departureDate}}</strong>, we can still assist you with <strong>{{suiteDescription}}</strong>.</p><p><strong>QUOTATION</strong> <em>(This quotation is exclusive to SA Rail – a division of Luxus Travel &amp; Tours)</em></p>{{quoteSummaryTable}}<p><strong>RESERVATION PROCEDURE</strong><br>Should you wish to proceed with a:</p><p><strong>Waitlist</strong> – kindly provide me with the first names, surnames &amp; dates of birth of all the guests travelling.</p><p><strong>Provisional Reservation</strong> – kindly provide me with the first names, surnames &amp; ID/Passport numbers of all the guests travelling. A provisional reservation can only be held for 72 hours.</p><p><strong>Definite Reservation</strong> – please complete and return the attached reservation form by email together with ID copies of all passengers travelling.</p><p><strong>BOOKING STATUS</strong><br>The booking status will only change to confirmed once your deposit has been received. The reservation will only be guaranteed once full payment has been received.</p><p><strong>PAYMENT TERMS</strong><br>A 25% non-refundable deposit is required within 72 hours of receiving your confirmation invoice to secure your reservation. The final payment is due 60 days before your departure. Should the reservation be made within 60 days before the departure period, the full amount will be due 48 hours after invoicing.</p><p>**Kindly ensure that payments are received on due dates to avoid cancellation.</p><p><strong>PAYMENT METHOD</strong><br>Payment can either be made by Electronic transfer (EFT) or Credit Card. We accept Mastercard and Visa card payments via PayGate, a secure online site. There is a 2.6% surcharge to partially cover the high credit card fees. Kindly request the payment link from your reservation consultant to use this facility.</p><p><strong>TICKETS &amp; VOUCHERS</strong><br>Once full payment is received, all your travel documents will be issued, and your vouchers will be sent to you electronically. Your actual train tickets will be provided at the station on the day of departure.</p><p><strong>CHANGES / CANCELLATION</strong><br>Our standard travel terms &amp; conditions apply to all reservations.</p><p><strong>INSURANCE</strong><br>It is highly recommended that clients obtain comprehensive travel insurance coverage that includes protection against trip cancellation penalties.</p><p><strong>CLIENT PROTECTION</strong><br>We are proud members of SATSA (membership number 2485) and insured through SATIB. As part of the Southern Africa Tourism Services Association, we are dedicated to raising tourism standards in South Africa.</p><p><strong>ADDITIONAL TRAVEL ARRANGEMENTS</strong><br>If you require assistance with any additional travel arrangements, such as flights, car rentals, accommodations, tours, or excursions, please do not hesitate to contact me. I am here to ensure that your travel experience is seamless and enjoyable.</p><p><strong>PLEASE FIND ATTACHED TO THIS EMAIL:</strong><br>1. Quotation in PDF <br>2. Reservation form with terms and conditions<br>3. Detailed train itinerary</p><p>Thank you for your enquiry. If you need any additional information or assistance, please don't hesitate to reach out. I look forward to your response.</p><p> </p>","version":25,"active":true,"created_at":"2026-07-13T20:23:38.992853+00:00","updated_at":"2026-08-17T11:18:13.199569+00:00","is_system":true,"name":null,"sort_order":0}]$seedjson$::json)
on conflict (key) do update set subject = excluded.subject, body_html = excluded.body_html, version = excluded.version, active = excluded.active, created_at = excluded.created_at, updated_at = excluded.updated_at, is_system = excluded.is_system, name = excluded.name, sort_order = excluded.sort_order;
alter table public.templates enable trigger user;
-- VOUCHER TEMPLATE (singleton — update in place, keep local id)
alter table public.voucher_template disable trigger user;
update public.voucher_template t set
  header_text = s.header_text,
  product_line = s.product_line,
  accent_colour = s.accent_colour,
  section_bg = s.section_bg,
  font_family = s.font_family,
  section_order = s.section_order,
  hidden_sections = s.hidden_sections,
  footer_company = s.footer_company,
  footer_phone = s.footer_phone,
  footer_email = s.footer_email,
  guidance_text = s.guidance_text,
  updated_at = s.updated_at,
  guidance_lead_text = s.guidance_lead_text
from json_populate_recordset(null::public.voucher_template, $seedjson$[{"id":"9979859a-5cf2-4c8b-b896-f76c217b5d02","header_text":"A division of Luxus Travel & Tours","product_line":"THE BLUE TRAIN • ROVOS RAIL • KRUGER SHALATI","accent_colour":"#0B2A3A","section_bg":"#1a3a4a","font_family":"Calibri, Candara, Segoe, 'Segoe UI', Optima, Arial, sans-serif","section_order":["guest_info","service_provider","footer"],"hidden_sections":[],"footer_company":"Luxus Travel & Tours","footer_phone":"","footer_email":"","guidance_text":"Please hand to your service provider. Pre-payment was made by Luxus Travel & Tours for all services mentioned below. Guests must settle extras direct with the service providers.","updated_at":"2026-08-18T13:32:53.894+00:00","guidance_lead_text":"Please hand to your service provider."}]$seedjson$::json) s
where true;
alter table public.voucher_template enable trigger user;
-- PAYMENT METHODS & SIGNATURE BRANDS
create temp table remap_payment_methods (old_id uuid, new_id uuid) on commit drop;
insert into remap_payment_methods (old_id, new_id)
select local.id, prod.new_id
from public.payment_methods local
join (values
    ('00c092d7-3e76-4176-8e60-16dfee10b083'::uuid, 'Primary'),
    ('d68da514-e6de-41c7-b0dd-82758b4caefd'::uuid, 'First National Bank (USD Account)')
  ) as prod(new_id, nat_key) on prod.nat_key = local.name
where local.id <> prod.new_id;

set session_replication_role = replica;

update public.invoices r set payment_method_id = m.new_id
from remap_payment_methods m where r.payment_method_id = m.old_id;

update public.payment_methods local set id = m.new_id
from remap_payment_methods m where local.id = m.old_id;

set session_replication_role = default;

alter table public.payment_methods disable trigger user;
